import{_ as e,o,c as r,a2 as t}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"Apariencia","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/user-guide/settings/appearance.md","filePath":"es-ES/user-guide/settings/appearance.md","lastUpdated":1785993908000}'),s={name:"es-ES/user-guide/settings/appearance.md"};function i(n,a,d,l,u,c){return o(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="apariencia" tabindex="-1">Apariencia <a class="header-anchor" href="#apariencia" aria-label="Permalink to &quot;Apariencia&quot;">​</a></h1><p>Fijada encima de <a href="./about.html">Acerca de</a> al final de la barra lateral. Dos grupos: <strong>Modo de tema</strong> y el propio selector de temas.</p><h2 id="modo-de-tema" tabindex="-1">Modo de tema <a class="header-anchor" href="#modo-de-tema" aria-label="Permalink to &quot;Modo de tema&quot;">​</a></h2><p>Tres tarjetas, haz clic para cambiar:</p><ul><li><strong>Claro</strong> — un único tema fijo, filtrado a los de tipo claro en la cuadrícula de abajo.</li><li><strong>Oscuro</strong> — igual, filtrado a los de tipo oscuro.</li><li><strong>Seguir el sistema</strong> (vista previa dividida claro/oscuro) — Lertaro alterna entre dos temas que eliges tú — uno para cuando Windows está en modo claro, otro para el oscuro — en lugar de usar un único tema fijo, y se actualiza de inmediato cada vez que cambias el propio ajuste de Windows (sin necesidad de reiniciar).</li></ul><p>Cambiar entre <strong>Claro</strong> y <strong>Oscuro</strong> salta al tema de ese tipo que hubieras seleccionado la última vez (la misma elección recordada que usa <strong>Seguir el sistema</strong> para su propio par claro/oscuro), así que ir y volver no pierde tu elección en ninguno de los dos lados.</p><h2 id="tema-de-interfaz" tabindex="-1">Tema de interfaz <a class="header-anchor" href="#tema-de-interfaz" aria-label="Permalink to &quot;Tema de interfaz&quot;">​</a></h2><p>Con <strong>Claro</strong> u <strong>Oscuro</strong> seleccionado arriba, una única cuadrícula de tarjetas lista solo los temas de ese tipo. Con <strong>Seguir el sistema</strong> seleccionado, la cuadrícula se divide en dos: <strong>Tema claro</strong> y <strong>Tema oscuro</strong> — cada una usa por defecto el tema del tipo correspondiente que resulte instalado primero, ya que qué temas existen en absoluto depende por completo de qué plugins de tema estén instalados.</p><p>Cada tema se muestra como una tarjeta, no solo un nombre: una pequeña maqueta de la ventana de búsqueda rápida (cuadro de búsqueda más un par de filas de resultado, una de ellas mostrada como seleccionada) renderizada con los propios colores de ese tema, para que puedas ver cómo se ve realmente un tema antes de cambiar a él. La tarjeta del tema activo muestra una insignia de marca de verificación.</p><p>Plugins de tema integrados e incluidos:</p><ul><li><strong>CoreExtensions</strong> (integrado) — Light, Dark, Nord, Sakura, Cyberpunk.</li><li><strong>AnimeThemes</strong> (incluido, si está instalado y habilitado) — Neon Genesis, Sakura Bloom, Weathering Blue.</li><li><strong>Curated Themes</strong> (incluido, si está instalado y habilitado) — diez pares claro/oscuro: Glacier, Terracotta, Forest, Amethyst, Crimson, Graphite, Indigo, Mint, Champagne y Amber.</li></ul><p>Cualquier otro plugin de tema puede añadir más tarjetas a la cuadrícula de la misma forma.</p>',12)])])}const g=e(s,[["render",i]]);export{p as __pageData,g as default};
